"""Small text helpers used across stages."""


def strip_bom(text):
    """Remove a UTF-8 byte-order mark, which Excel loves to prepend."""
    if text.startswith("﻿"):
        return text[1:]
    return text


def normalize_header(name):
    """Normalize a column header to snake_case.

    "Order ID " -> "order_id"; embedded runs of junk collapse to a
    single underscore so headers stay readable.
    """
    out = []
    prev_us = False
    for ch in strip_bom(name).strip().lower():
        if ch.isalnum():
            out.append(ch)
            prev_us = False
        elif not prev_us:
            out.append("_")
            prev_us = True
    return "".join(out).strip("_")


def truncate(text, limit=60):
    """Shorten `text` for log lines; never mid-word surgery, just a cut."""
    text = str(text)
    if len(text) <= limit:
        return text
    return text[: limit - 3] + "..."


def is_blank(value):
    """True for None or a string of only whitespace."""
    return value is None or (isinstance(value, str) and not value.strip())


def pluralize(count, singular, plural=None):
    """'1 record', '3 records' — keeps log messages grammatical."""
    if count == 1:
        return "%d %s" % (count, singular)
    return "%d %s" % (count, plural or singular + "s")

"""Validation rules.

Each rule is a callable `rule(record, check, state) -> None` that raises
CheckFailure to reject the record. `state` is a per-run dict scoped to
one check instance, used by stateful rules such as `unique`.
"""

import datetime

from .errors import CheckFailure
from .utils.numbers import parse_decimal, parse_int
from .utils.text import is_blank


def rule_required(record, check, state):
    field = check["field"]
    if field not in record or is_blank(record[field]):
        raise CheckFailure("required field %r is missing or blank" % field, field=field)


def rule_type(record, check, state):
    """Check that the field parses as the declared type without changing it."""
    field = check["field"]
    if field not in record or is_blank(record[field]):
        return  # absence is `required`'s business, not ours
    expected = check.get("type", "str")
    value = record[field]
    try:
        if expected == "int":
            parse_int(value)
        elif expected == "decimal":
            parse_decimal(value)
        elif expected == "date":
            datetime.date.fromisoformat(str(value).strip())
        elif expected == "bool":
            if str(value).strip().lower() not in ("true", "false", "1", "0"):
                raise ValueError("not a boolean: %r" % value)
    except ValueError as exc:
        raise CheckFailure(str(exc), field=field)


def rule_range(record, check, state):
    field = check["field"]
    if field not in record or is_blank(record[field]):
        return
    try:
        value = parse_decimal(record[field])
    except ValueError as exc:
        raise CheckFailure(str(exc), field=field)
    low = check.get("min")
    high = check.get("max")
    if low is not None and value < parse_decimal(low):
        raise CheckFailure(
            "%s=%s is below the minimum %s" % (field, value, low), field=field
        )
    if high is not None and value > parse_decimal(high):
        raise CheckFailure(
            "%s=%s is above the maximum %s" % (field, value, high), field=field
        )


def rule_one_of(record, check, state):
    field = check["field"]
    if field not in record or is_blank(record[field]):
        return
    allowed = check.get("values", [])
    if record[field] not in allowed:
        raise CheckFailure(
            "%s=%r is not one of %s" % (field, record[field], ", ".join(allowed)),
            field=field,
        )


def rule_unique(record, check, state):
    """Reject records whose key fields repeat an earlier record's."""
    fields = check.get("fields") or [check["field"]]
    key = tuple(str(record.get(f, "")) for f in fields)
    seen = state.setdefault("seen", set())
    if key in seen:
        raise CheckFailure(
            "duplicate value for %s: %s" % ("+".join(fields), "/".join(key)),
            field=fields[0],
        )
    seen.add(key)


def rule_matches(record, check, state):
    """Substring / prefix check — deliberately not full regex to keep specs tame."""
    field = check["field"]
    if field not in record or is_blank(record[field]):
        return
    value = str(record[field])
    prefix = check.get("prefix")
    contains = check.get("contains")
    if prefix is not None and not value.startswith(prefix):
        raise CheckFailure(
            "%s=%r does not start with %r" % (field, value, prefix), field=field
        )
    if contains is not None and contains not in value:
        raise CheckFailure(
            "%s=%r does not contain %r" % (field, value, contains), field=field
        )


RULES = {
    "required": rule_required,
    "type": rule_type,
    "range": rule_range,
    "one_of": rule_one_of,
    "unique": rule_unique,
    "matches": rule_matches,
}

"""Input readers.

Both readers return a list of dicts with string keys. CSV headers are
normalized to snake_case on the way in (see utils.text.normalize_header)
so specs can always refer to fields in one canonical spelling.
"""

import csv
import json
import os

from ..errors import ExtractError
from ..utils.text import normalize_header


def read_records(path, fmt):
    """Dispatch to the reader for `fmt`."""
    if not os.path.exists(path):
        raise ExtractError("source file not found: %s" % path)
    if fmt == "csv":
        return read_csv(path)
    if fmt == "jsonl":
        return read_jsonl(path)
    raise ExtractError("no reader for format %r" % fmt)


def read_csv(path):
    """Read a CSV file into a list of dicts, normalizing headers."""
    try:
        with open(path, "r", encoding="utf-8-sig", newline="") as fh:
            reader = csv.reader(fh)
            rows = list(reader)
    except (OSError, csv.Error) as exc:
        raise ExtractError("could not read CSV %s: %s" % (path, exc))

    if not rows:
        raise ExtractError("CSV %s is empty (no header row)" % path)

    header = [normalize_header(h) for h in rows[0]]
    seen = set()
    for name in header:
        if not name:
            raise ExtractError("CSV %s has a blank column header" % path)
        if name in seen:
            raise ExtractError(
                "CSV %s has duplicate column %r after normalization" % (path, name)
            )
        seen.add(name)

    records = []
    for lineno, row in enumerate(rows[1:], start=2):
        if not any(cell.strip() for cell in row):
            continue  # skip fully blank lines
        if len(row) != len(header):
            raise ExtractError(
                "CSV %s line %d has %d cells, expected %d"
                % (path, lineno, len(row), len(header))
            )
        record = dict(zip(header, (cell.strip() for cell in row)))
        record["_line"] = lineno
        records.append(record)
    return records


def read_jsonl(path):
    """Read a JSON-lines file into a list of dicts."""
    records = []
    try:
        with open(path, "r", encoding="utf-8") as fh:
            for lineno, line in enumerate(fh, start=1):
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                except json.JSONDecodeError as exc:
                    raise ExtractError(
                        "JSONL %s line %d is not valid JSON: %s" % (path, lineno, exc)
                    )
                if not isinstance(obj, dict):
                    raise ExtractError(
                        "JSONL %s line %d is not an object" % (path, lineno)
                    )
                obj["_line"] = lineno
                records.append(obj)
    except OSError as exc:
        raise ExtractError("could not read JSONL %s: %s" % (path, exc))
    return records

